const codePart = await browserjs(tabId, async () => {
  const res = await fetch("https://www.movingapt.com/wp-content/cache/min/1/wp-content/plugins/movingapt-widget/cost_calculator.js?ver=1789623901");
  const text = await res.text();
  const idx = text.indexOf('miles =') > -1 ? text.indexOf('miles =') : text.indexOf('miles=Math');
  if (idx !== -1) return text.slice(Math.max(0, idx - 100), Math.min(text.length, idx + 800));
  // Find where miles is assigned
  const matches = [];
  const regex = /miles\s*=[^;]+;/g;
  let m;
  while ((m = regex.exec(text)) !== null) {
    matches.push(m[0]);
  }
  return matches;
});
console.log("Miles assignments:", codePart);

