const res = await browserjs(tabId, async () => {
  // Reset calculator to step 1
  jQuery('.cost_calculator .step').hide();
  jQuery('.cost_calculator .step1').show();
  jQuery('#sizeCalc').val("3000"); // 1 Bedroom
  jQuery('#dateCalc').val("10/15/2026");

  // Go to step 2
  jQuery('.cost_calculator .step1 .btn-next').click();
  await new Promise(r => setTimeout(r, 500));

  // Set From
  const fromInput = jQuery('.cost_calculator .zipCodeFrom');
  fromInput.focus();
  fromInput.val("Pittsburgh").trigger('keyup');

  // Wait for ajax
  let waited = 0;
  while (waited < 3000 && jQuery('.zipFromResult .custom-list-group-item').length === 0) {
    await new Promise(r => setTimeout(r, 200));
    waited += 200;
  }
  const fromItems = jQuery('.zipFromResult .custom-list-group-item');
  if (fromItems.length > 0) {
    fromItems.first().click();
  }

  // Set To
  const toInput = jQuery('.cost_calculator .zipCodeTo');
  toInput.focus();
  toInput.val("San Francisco").trigger('keyup');

  waited = 0;
  while (waited < 3000 && jQuery('.zipToResult .custom-list-group-item').length === 0) {
    await new Promise(r => setTimeout(r, 200));
    waited += 200;
  }
  const toItems = jQuery('.zipToResult .custom-list-group-item');
  if (toItems.length > 0) {
    toItems.first().click();
  }

  await new Promise(r => setTimeout(r, 500));

  // Click next on step 2
  jQuery('.cost_calculator .step2 .btn-next').click();

  await new Promise(r => setTimeout(r, 1500));

  return {
    fromVal: fromInput.val(),
    toVal: toInput.val(),
    step4Visible: jQuery('.cost_calculator .step4').is(':visible'),
    step4Text: jQuery('.cost_calculator .step4').text().trim(),
    miles: window.miles || "not global"
  };
});
