const tabsToCheck = [
  { name: "MovingAPT", tabId: 787784079 },
  { name: "International Van Lines", tabId: 787784080 },
  { name: "PODS", tabId: 787784081 },
  { name: "U-Pack", tabId: 787784082 },
  { name: "U-Haul", tabId: 787784083 }
];

const results = [];

for (const t of tabsToCheck) {
  const data = await browserjs(t.tabId, () => {
    // Find TrustScore and review count
    const scoreEl = document.querySelector('[data-rating-typography]') || document.querySelector('.typography_heading-m__gnuuj') || Array.from(document.querySelectorAll('*')).find(el => el.textContent.match(/^\d\.\d$/) && el.children.length === 0);
    const score = scoreEl ? scoreEl.textContent.trim() : null;

    // Find reviews count
    const reviewsEl = Array.from(document.querySelectorAll('*')).find(el => el.textContent.match(/[\d,]+\s*reviews?/i) && el.children.length === 0);
    const reviews = reviewsEl ? reviewsEl.textContent.trim() : null;

    // Category rank or stars text
    const starsEl = document.querySelector('[data-service-review-rating-typography]') || document.querySelector('[class*="star-rating"]');

    return {
      title: document.title,
      url: window.location.href,
      score,
      reviews,
      bodySnippet: document.body.innerText.slice(0, 500).replace(/\n+/g, ' ')
    };
  });
  results.push({ company: t.name, tabId: t.tabId, ...data });
}

console.log("Trustpilot Live Ratings:", JSON.stringify(results, null, 2));

